from __future__ import absolute_import
import os
import logging
import tempfile
from pyvirtualdisplay import Display
from taf.internal.aliasing import aliasing_scope
from selenium.webdriver.remote.webdriver import WebDriver
from taf.selenium.core.robotkeywords.keywords import SeleniumOAMKeywords
from taf.selenium.core.webdrivers import CustomWebDriverFirefox, CustomWebDriverChrome
from taf.selenium.sc.common.download import DownloadChecker
from taf.selenium.sc.provider import Provider
from taf.selenium.sc.facade import Sc
from taf.selenium.sc.common.debug import (catch_interface_exception, catch_intercepted_click_exception)


class sc(SeleniumOAMKeywords):
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'
    DOWNLOAD_DIR_SUFFIX = 'taf_selenium_sc_download'
    DEBUG_DIR_SUFFIX = 'taf_selenium_sc_screenshot'
    lookup_handler, store = aliasing_scope(name=__name__, lookup_arg='sc', lookup_type=Sc)

    def __init__(self):
        super(sc, self).__init__()
        self._download_checker = None
        self._debug_dir = None
        self._display = None
        self.__driver = None

    def enable_virtual_display(self, width=1920, height=1280):
        """
        This keyword is used to enable virtual display - with it enabled browser
        window will not be displayed on screen.

        In order for this functionality to work correctly this keyword must to be
        called before `Login` keyword is called (which would spawn browser window).

        Please make sure "xvfb" service is installed on the environment.

        :param width: width of browser
        :type width: int
        :param height: int, height of browser
        :type height: int
        """
        self._display = Display(visible=0, size=(width, height))
        self._display.start()

    def disable_virtual_display(self):
        """
        This keyword is used to disable virtual display.
        Please make sure to call this method at the end of test if you've call "enable_virtual_display"
        """
        self._display.stop()

    @property
    def download_dir(self):
        return self._download_dir

    def _set_download_dir(self, download_dir):
        if download_dir and download_dir != '/':
            self._download_dir = download_dir
        else:
            self._download_dir = tempfile.mkdtemp(suffix=self.DOWNLOAD_DIR_SUFFIX)

    @property
    def screenshot_dir(self):
        return self._screenshot_dir

    def _set_default_screenshot_dir(self, screenshot_dir):
        if screenshot_dir:
            self._create_screenshot_dir(screenshot_dir)
        else:
            self._create_screenshot_dir(self._download_dir)

    def _create_screenshot_dir(self, dir_path):
        self._screenshot_dir = os.path.join(dir_path, self.DEBUG_DIR_SUFFIX)
        if not os.path.exists(self._screenshot_dir):
            os.makedirs(self._screenshot_dir)

    def _create_download_checker(self):
        self._download_checker = DownloadChecker(self._download_dir)

    def get_alias_value(self, alias):
        if "::" not in alias:
            alias = "::".join([self._namespace, alias])
        return self._builtin.get_variable_value("${%s}" % alias)

    def _create_driver(self, driver):
        if isinstance(driver, WebDriver):
            self.__driver = driver
            logging.info('WebDriver with ID {} is created'.format(self.__driver))
            return self.__driver

        driver_name = str(driver)
        driver_obj = self.get_alias_value(driver_name)
        if driver_obj and isinstance(driver_obj, WebDriver):
            self.__driver = driver_obj
            logging.info('WebDriver named "{}" with ID {} is automatically created'.format(driver_name, self.__driver))
            return self.__driver
        else:
            notification = '''Can not find webdriver named "{}" within robot variable scope!!!
            If you are trying to use self-created webdriver, please read suggestions as below:
            1. check if webdriver name {} is matched with the configured one;
            2. check if correct robot variable scope is set in "set_scope"(global, suite, test can be used)
            method within robot case'''.format(driver_name, driver_name)
            logging.info(notification)

        if driver_name == "Chrome":
            self.__driver = CustomWebDriverChrome(self.download_dir)
            logging.info('ChromeWebDriver "{}" with ID {} is automatically created'.format(driver_name, self.__driver))
        elif driver_name == "Firefox":
            self.__driver = CustomWebDriverFirefox(self.download_dir)
            logging.info('FirefoxWebDriver "{}" with ID {} is automatically created'.format(driver_name, self.__driver))
        else:
            raise AttributeError('Created webdriver failed, please check browser name "{}"'.format(driver_name))
        return self.__driver

    def _configure_before_login(self, download_dir, screenshot_dir):
        self._set_download_dir(download_dir)
        self._set_default_screenshot_dir(screenshot_dir)
        self._create_download_checker()

    def _initiate_sc(self, browser, version):
        driver = self._create_driver(browser)
        driver.maximize_window()
        sc_cls = Provider.provide(version)
        return sc_cls(driver, self._download_checker, self._screenshot_dir)

    def login(self, url, username, password, timeout=60, download_dir=None, screenshot_dir=None, version="sc",
              browser='Firefox', alias=None):
        """
        Keyword for login into sc web.
        Usage example:
        1) If you want to test feature that only exist in sc "5G20B", and use "Chrome" as testing browser
        *** Settings ***
        Library    taf.selenium.sc    WITH NAME      sc

        *** Variables ***
        ${WEBUI_URL}    xxx.xxx.xxx.xxx
        ${WEBUI_NAME}    Nemuadmin
        ${WEBUI_PWD}     nemuuser

        *** Test Cases ***
        Case Name
        sc.login   ${WEBUI_URL}   ${WEBUI_NAME}   ${WEBUI_PWD}   version=5G20B    browser=Chrome

        2) If you want to use firefox webdriver created by yourself (please notice that the "driver" has to be
        instance of Webdriver or its child class)
        *** Settings ***
        Library    taf.selenium.sc    WITH NAME      sc

        *** Variables ***
        ${download_dir}    xxxx
        ${driver_alias}    myDriver
        ${driver_scope}    suite
        ${WEBUI_URL}    xxx.xxx.xxx.xxx
        ${WEBUI_NAME}    Nemuadmin
        ${WEBUI_PWD}     nemuuser

        *** Test Cases ***
        Case Name
        sc.create_firefox_web_driver    ${download_dir}    ${driver_alias}
        sc.set_scope    ${driver_scope}
        sc.login  ${WEBUI_URL} ${WEBUI_NAME} ${WEBUI_PWD}  downlaod_dir=${download_dir}  browser=${driver_alias}

        3) If you want to start-up several testing browser (login interface supports to pass different alias name to
        distinguish different browser you created)
        *** Settings ***
        Library    taf.selenium.sc    WITH NAME      sc

        *** Variables ***
        ${WEBUI_URL}    xxx.xxx.xxx.xxx
        ${WEBUI_NAME}    Nemuadmin
        ${WEBUI_PWD}     nemuuser

        *** Test Cases ***
        Case Name
        sc.login   ${WEBUI_URL}   ${WEBUI_NAME}  ${WEBUI_PWD}  version=5G20B  browser=Chrome   alias=sc1
        sc.login   ${WEBUI_URL}   ${WEBUI_NAME}  ${WEBUI_PWD}  browser=Firefox   alias=sc2

        :param url: url to sc web
        :type url: str
        :param username: username
        :type username: str
        :param password: password
        :type password: str
        :param timeout: timeout
        :type timeout: int
        :param download_dir: file downloaded dir
        :type download_dir: str
        :param screenshot_dir: screenshot dir
        :type screenshot_dir: str
        :param version: version string, defalut is sc
        :type version: str
        :param browser: WebDriver instance or "Chrome" or "Firefox" or alias name for self-created webdriver
        :type browser: Optional[WebDriver, str]
        :param alias:  (optional) alias that the new sc object will be identified by
        If not specified, default alias is used: "None"
        :type alias: str
        :return: error msg if it exists after login
        :rtype: None or str
        """
        self._configure_before_login(download_dir, screenshot_dir)
        sc = self._initiate_sc(browser, version)
        login_msg = sc.login(url, username, password, self._download_checker, self._screenshot_dir, timeout)
        self.store.add(sc, alias)
        return login_msg

    @catch_interface_exception
    @lookup_handler.implicit_lookup
    def block_prrh(self, prrh, timeout=60, sc=None):
        """
        Keyword for blocking prrh

        :param prrh: prrh module name, eg. ANTMOD-1
        :type prrh: str
        :param timeout: timeout
        :type timeout: int or str
        :param sc: alias (string) – (optional) alias that the new sc object will be identified by.
        If not specified, default alias is used: "None"
        :type sc: str
        :return: True if successfully block prrh, or False
        :rtype: bool
        """
        sc.topology.hardware.navigate_to()
        return sc.topology.hardware.block_prrh(prrh, int(timeout))

