    @catch_interface_exception
    @lookup_handler.implicit_lookup
    def set_parameter(self, dist_name, abbreviation, new_value, prevalidate=False, timeout=60, sc=None):
        """
        Keyword for setting parameter under parameter editor page

        :param dist_name: dist name to filter target object, eg. ASI-3263/BTS-1/CELL-1/CHANNELGROUP-1/CHANNEL-1
        :type dist_name: str
        :param abbreviation: abbreviation to filter target parameter, eg. targetDirection, antAntlPrDN [0]
        :type abbreviation: str
        :param new_value: new value for target parameter
        :type new_value: str
        :param prevalidate: prevalidate parameters, defalut False
        :type prevalidate: Boolean
        :param timeout: timeout
        :type timeout: int or str
        :param sc: alias (string) – (optional) alias that the new sc object will be identified by.
        If not specified, default alias is used: "None"
        :type sc: str
        """
        sc.configuration_management.parameter_editor.navigate_to()
        sc.configuration_management.parameter_editor.set_parameter(dist_name,
                                                                   abbreviation,
                                                                   new_value,
                                                                   prevalidate=prevalidate,
                                                                   timeout=int(timeout))

